function lineDiff(before,after){const a=before.split('\n'),b=after.split('\n');let prefix=0,suffix=0;while(prefix<Math.min(a.length,b.length)&&a[prefix]===b[prefix])prefix++;while(suffix<Math.min(a.length,b.length)-prefix&&a.at(-suffix-1)===b.at(-suffix-1))suffix++;const left=a.slice(prefix,a.length-suffix),right=b.slice(prefix,b.length-suffix),lines=a.slice(0,prefix).map(text=>[' ',text]);if(left.length*right.length<=2000000){const rows=Array.from({length:left.length+1},()=>new Uint32Array(right.length+1));for(let i=left.length-1;i>=0;i--)for(let j=right.length-1;j>=0;j--)rows[i][j]=left[i]===right[j]?rows[i+1][j+1]+1:Math.max(rows[i+1][j],rows[i][j+1]);let i=0,j=0;while(i<left.length||j<right.length){if(i<left.length&&j<right.length&&left[i]===right[j]){lines.push([' ',left[i]]);i++;j++;}else if(j<right.length&&(i===left.length||rows[i][j+1]>rows[i+1][j]))lines.push(['+',right[j++]]);else lines.push(['-',left[i++]]);}}else{left.forEach(text=>lines.push(['-',text]));right.forEach(text=>lines.push(['+',text]));}if(suffix)a.slice(a.length-suffix).forEach(text=>lines.push([' ',text]));return lines;}
function renderWorld(target,task){const runs=task.runs||[];if(!runs.length){empty(target,'先有世界描述，再有场景代码','每次 run 的 YAML 与 Python 快照会在这里成对归档。','⌗');return;}const selected=selectedRun(task,S.worldRun),index=runs.indexOf(selected),base=runs.find(r=>r.id===S.diffRun)||runs[index-1];const controls=make('div','world-toolbar');controls.append(runChoices(task,selected.id,id=>{S.worldRun=id;S.diffRun=null;S.bodyKey=null;renderTask();},'查看 run'));const compare=make('label','run-choice');compare.append(make('span','','对比基线'));const select=make('select');select.setAttribute('aria-label','Diff 基线');const noDiff=make('option','','不对比，查看原文');noDiff.value='';select.append(noDiff);runs.filter(r=>r.id!==selected.id).forEach(r=>{const o=make('option','',`Run ${runs.indexOf(r)+1}`);o.value=r.id;select.append(o);});select.value=base?.id||'';select.onchange=()=>{S.diffRun=select.value||'none';S.bodyKey=null;renderTask();};compare.append(select);controls.append(compare);target.append(controls);const fileTabs=make('div');tabs(fileTabs,[['world.yaml','World state · YAML'],['scene.py','场景 · Python'],['local_memory.md','局部 Memory']],S.worldFile,file=>{S.worldFile=file;S.bodyKey=null;renderTask();});target.append(fileTabs,make('p','payload-note','runs/ 保存每次 run 的不可变快照；work/ 是后续 run 可继续修改的工作副本。此处只展示归档快照，避免重复。'));const holder=make('div','panel source-panel');target.append(holder);loading(holder);const effectiveBase=S.diffRun==='none'?null:base;const path=`runs/${selected.id}/${S.worldFile}`;Promise.all([artifactText(path,task.id),effectiveBase?artifactText(`runs/${effectiveBase.id}/${S.worldFile}`,task.id):Promise.resolve(null)]).then(([after,before])=>{if(!holder.isConnected)return;holder.replaceChildren();const head=make('div','source-heading');head.append(make('span','',before!==null?`Run ${runs.indexOf(effectiveBase)+1} → Run ${index+1}`:`Run ${index+1} · ${S.worldFile}`),artifactLink('下载此 run 原文件',path,task.id));holder.append(head);const pre=make('pre','code source-code');if(before!==null){const lines=lineDiff(before,after),added=lines.filter(x=>x[0]==='+').length,removed=lines.filter(x=>x[0]==='-').length;head.append(make('small','',`+${added} / −${removed}`));lines.forEach(([kind,text])=>pre.append(make('span',`diff-line ${kind==='+'?'plus':kind==='-'?'minus':''}`,kind+text)));}else pre.textContent=after;holder.append(pre);}).catch(e=>{if(holder.isConnected)holder.replaceChildren(paragraph(e.message,'error'));});const extras=(task.artifacts||[]).filter(item=>{const path=artifactPath(item);return path.startsWith(`runs/${selected.id}/`)&&!/\/(world\.yaml|scene\.py|local_memory\.md)$/.test(path)&&/\.(yaml|py|json)$/.test(path);});if(extras.length){const host=make('div'),d=detail('此 run 的中间快照与渲染记录',host);d.addEventListener('toggle',()=>{if(d.open&&!host.childElementCount)renderFiles(host,extras,task.id);});target.append(d);}}
function renderFiles(target,files,taskId=S.id){const list=make('div','file-list');files.forEach(item=>{const path=artifactPath(item),b=button('',()=>openArtifact(path,taskId),'file-row');b.append(make('span','',path),make('small','','查看源文件 ↗'));list.append(b);});target.append(list);}
async function openArtifact(path,taskId=S.id){inspect(path,'正在读取…');const target=$('#inspector');if(!/\.(ya?ml|py|md|json|log|txt|csv)$/i.test(path)){target.replaceChildren();const head=make('div','inspector-heading');head.append(make('h2','',path),button('×',closeInspector,'icon-button'));target.append(head,artifactLink('下载原文件',path,taskId));return;}const revision=S.revision;try{const response=await fetch(artifactURL(path,taskId));if(!response.ok)throw Error(await response.text());const text=await response.text();if(revision!==S.revision||target.hidden)return;target.replaceChildren();const head=make('div','inspector-heading');head.append(make('h2','',path),button('×',closeInspector,'icon-button'));target.append(head,artifactLink('下载原文件',path,taskId),make('p','payload-note','原始源文件 · 按需读取'));if(path.endsWith('.json')){try{target.append(jsonTree(JSON.parse(text)));}catch{target.append(make('pre','code',text));}}else target.append(make('pre','code',text));}catch(e){if(revision===S.revision)inspect(path,e.message);}}
function renderArtifacts(target,items,taskId=S.id){const pictures=items.filter(item=>/\.(png|jpe?g|webp|gif|mp4|webm|mov)$/i.test(artifactPath(item))),grid=make('div','media-grid');target.append(grid);let offset=0;const more=button('',add,'secondary small');function add(){more.remove();pictures.slice(offset,offset+24).forEach(item=>{const path=artifactPath(item),card=make('div','media-card'),caption=make('div','media-caption');caption.append(make('span','',path),artifactLink('原文件',path,taskId));card.append(mediaElement(path,taskId),caption);grid.append(card);});offset+=24;if(offset<pictures.length){more.textContent=`继续显示媒体（剩余 ${pictures.length-offset}）`;grid.after(more);}}add();}
function renderTaskRSI(target,task){if(task.kind==='threat')renderEditFeedback(target,task);else target.append(metricPanel(task,null,'当前任务的参考指标'));if(task.task_critic_error)target.append(paragraph('Task RSI critic 失败，任务评测已保留：'+task.task_critic_error,'error'));if(task.critique)renderSummary(target,task.critique,'Task 总结与经验');if(task.candidate_version){const host=make('div');target.append(host);loadCandidateCard(host,task.candidate_version,task.id);}else{const p=make('div','policy-note',['test','validation','heldout','held-out','held_out'].includes(task.split)?'验证与保留集任务只保留重建、run critique、指标与成本，不执行任务级总结或外围 RSI。':task.config?.outer_rsi===false?task.kind==='threat'?'此任务未启用共享经验提炼；编辑结果和 run critic 仍会保留。':'此任务的外层 RSI 已关闭：仍会自动完整评测并保留 run critic，不执行 task RSI critic。':task.kind==='threat'?'任务总结后，共享技能候选和 Git diff 会显示在这里。':'任务结束并执行外层 RSI 后，候选版本、Git diff 和新版本试验会显示在这里。');target.append(p);}const trials=task.trials||[];if(task.kind!=='threat'&&trials.length){target.append(make('div','section-label','原场景 ↔ RSI 后版本 · 逐次试验'));trials.forEach(trial=>renderTrial(target,trial));}}
async function loadCandidateCard(host,id,sourceTask){loading(host);const revision=S.revision;try{const version=await api(`/api/versions/${encodeURIComponent(id)}`);if(revision!==S.revision||!host.isConnected)return;host.replaceChildren();renderCandidate(host,version,sourceTask);}catch(e){if(host.isConnected)host.replaceChildren(paragraph(e.message,'error'));}}
function renderCandidate(target,version,sourceTask){const card=make('section','panel rsi-candidate'),header=make('div','candidate-header'),text=make('div');text.append(make('h3','',`${version.active||version.status==='active'?'当前版本':!version.parent?'初始版本':'候选版本'} ${short(version.id)}`),make('div','metadata',`父版本 ${short(version.parent)} · 来源 ${short(sourceTask||version.task_id)}`));header.append(make('span','candidate-mark','⑂'),text,badge(version.status==='accepted'&&version.scope?.kind==='campaign'?'实验内采纳':version.status));card.append(header);if(version.scope?.kind==='campaign')card.append(make('p','check-description',`采纳范围：实验 ${version.scope.id}。该分支的版本和证据独立保留。`));if(version.summary)card.append(make('p','candidate-summary',version.summary));card.append(make('p','check-description',version.adoption?.mode==='user_requested_maintenance'?'已按用户要求更新提示词；这是维护版本，没有宣称重建指标提升。':version.adoption?.mode==='experiment_auto'?'已按进化实验策略自动采纳；该状态不表示所有指标均有提升。':version.adoption?.mode==='manual'?'已由用户在工作台手动确认采纳。':'指标与场景供你判断。单任务不会因为试验完成而自动采纳新版本。'));
  const actions=make('div','candidate-actions'),active=activeVersion(),stale=version.parent&&active&&version.parent!==active,unavailable=version.status==='active'||version.active||candidateBusy(version),managed=campaignManaged(version);
  const diff=button('查看 Git diff',()=>{S.mode='versions';selectRecord(version.id);},'secondary small'),trial=button('使用新版本试验',()=>versionAction(version.id,'trial',{task_id:sourceTask||version.task_id}),'secondary small'),reject=button('拒绝',()=>versionAction(version.id,'reject'),'text-button danger'),adopt=button('采纳此版本',()=>versionAction(version.id,'adopt',{reason:'用户在工作台手动确认'}),'primary');trial.disabled=unavailable||!version.parent||!(sourceTask||version.task_id);reject.disabled=unavailable||managed||!version.parent||version.status==='rejected';adopt.disabled=unavailable||managed||!version.parent||stale||version.status==='rejected';actions.append(diff,trial,reject,adopt);if(managed&&!SAFE)actions.append(button('打开所属实验',()=>{S.mode='campaigns';selectRecord(version.campaign_id);},'secondary small'));if(SAFE)trial.remove();card.append(actions);if(stale)card.append(make('p','check-description','候选基于历史父版本，无法覆盖当前活动版本。'));target.append(card);}
async function versionAction(id,action,value={}){notice();try{const response=await post(`/api/versions/${encodeURIComponent(id)}/${action}`,value);await refresh();if(S.mode==='tasks'&&S.id)await selectTask(S.id,true);else if(S.mode==='versions')await selectRecord(id,true);if(action==='trial')notice('已启动候选版本试验。新任务完成后会列出场景、完整官方指标与实际消耗。');else if(action==='adopt')notice('已按你的确认采纳此版本。');else if(action==='reject')notice('已记录拒绝该候选版本。');return response;}catch(e){notice(e.message);}}
function renderTrial(target,trial){const card=make('section','panel trial-card'),head=make('div','trial-header'),title=make('div');title.append(make('h3','',`新版本试验 · ${short(trial.candidate_version)}`),make('div','metadata',trial.id||''));head.append(title,badge(trial.status));card.append(head);target.append(card);const before=trial.baseline||{},after=trial.candidate||{};const grid=make('div','scene-grid');card.append(grid);renderArm(grid,before,'原版本场景');renderArm(grid,after,'RSI 后版本场景');card.append(metricPanel(before,after,'相同输入的指标对照'));if(trial.error)card.append(paragraph(trial.error,'error'));if(trial.comparability||trial.limits||trial.notes)card.append(rawDetails('试验协议与可比性',trial.comparability||trial.limits||trial.notes));const links=make('div','trial-links');if(before.task_id)links.append(button('打开原任务',()=>selectTask(before.task_id),'text-button'));if(after.task_id)links.append(button('打开新版本场景任务',()=>selectTask(after.task_id),'text-button'));card.append(links,rawDetails('完整试验记录',trial));target.append(card);}
async function selectRecord(id,preserve=false){const revision=++S.revision;S.controller?.abort();S.controller=new AbortController();S.id=id;S.task=null;S.bodyKey=null;if(!preserve)closeInspector();setNavigation();updateSidebar();history.replaceState(null,'',`#${S.mode==='versions'?'version':'campaign'}/${encodeURIComponent(id)}`);const target=$('#content');if(!preserve)loading(target);try{const record=await api(`/api/${S.mode}/${encodeURIComponent(id)}`,{signal:S.controller.signal});if(revision!==S.revision)return;target.replaceChildren();if(S.mode==='versions')renderVersion(target,record);else renderCampaign(target,record);}catch(e){if(e.name!=='AbortError')notice(e.message);}}
function renderVersion(target,version){heading(target,`版本 ${short(version.id)}`,`${time(version.created_at)} · ${version.parent?'父版本 '+short(version.parent):'初始空 skills；基础 prompt 由固定 harness 管理'}`,[],'VERSION & DIFF');renderCandidate(target,version,version.task_id);const parts=make('div','component-tabs'),content=make('div'),components=version.components||{};['skills',...['prompts','memory'].filter(kind=>Object.keys(components).some(path=>path.startsWith(kind+'/')))].forEach(kind=>{const count=Object.keys(components).filter(path=>path.startsWith(kind+'/')).length,b=button(`${kind==='prompts'?'Prompt':kind==='skills'?'Skill':'全局 Memory'} · ${count}`,()=>{S.component=kind;draw();},S.component===kind?'active':'');b.dataset.component=kind;parts.append(b);});target.append(parts,content);function draw(){parts.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.component===S.component));content.replaceChildren();const entries=Object.entries(components).filter(([path])=>path.startsWith(S.component+'/'));if(!entries.length)empty(content,'该组件保持为空','没有预置经验；有任务证据支持时才新增。','⑂');entries.forEach(([path,text])=>{const panel=make('section','panel summary-panel');panel.append(make('h3','mono',path),make('pre','code',text));content.append(panel);});}draw();target.append(make('div','section-label','GIT DIFF'));const diff=make('pre','code card');(version.diff||'初始版本，无父版本差异。').split('\n').forEach(line=>diff.append(make('span',`diff-line ${line.startsWith('+')?'plus':line.startsWith('-')?'minus':line.startsWith('@@')?'hunk':''}`,line)));target.append(diff);(version.trials||[]).forEach(trial=>renderTrial(target,trial));if(version.evaluation)target.append(rawDetails('外部评估记录',version.evaluation));if(!SAFE&&version.parent&&version.task_id){const advanced=make('div');advanced.append(make('p','muted small','在配置的评估输入上比较父版本与候选版本；结果仍供人工确认。'),button('运行外部评估',()=>versionAction(version.id,'evaluate'),'secondary small'));target.append(detail('更多评估操作',advanced));}}
async function showCampaignHome(){
  const target=$('#content');target.replaceChildren();
  heading(target,'选择样本，逐轮验证 RSI','先完成 V0 全量测试 → 每个进化样本执行一个 task 并总结 RSI → 每轮再完整测试。测试集始终固定。',[],'EVOLUTION EXPERIMENT');
  const cfg=normalizeConfig(S.state.config);cfg.campaign={...cfg.campaign,outer_rsi:true,trial_enabled:true};
  const form=make('form','panel campaign-composer'),body=make('div','panel-body'),selection={evolution:[],test:[]};
  const controls=configForm(cfg,{campaign:true});body.append(controls);
  // These two phases are mandatory for a reconstruction + RSI experiment.
  for(const key of ['campaign.outer_rsi','campaign.trial_enabled']){const input=controls.querySelector('[data-config="'+key+'"]');if(input){input.checked=true;input.disabled=true;}}
  const summary=make('p','policy-note','请选择互不重叠的进化集和测试集。'),grids=make('div','campaign-selection'),columns={};
  for(const [key,label] of [['evolution','进化集 · 按勾选顺序逐个进化'],['test','测试集 · 每个版本全部重建与评测']]){
    const column=make('section','campaign-dataset');column.append(make('h3','',label));const grid=make('div','input-picker');grid.dataset.split=key;columns[key]=grid;column.append(grid);grids.append(column);
  }
  body.append(summary,grids,make('p','muted small','样本角色仅在本实验内冻结；进化与测试不允许同一视频。测试不会生成跨 task skills。VQA 使用原生题库及 Kimi K3。'));
  const footer=make('div','composer-footer'),start=make('button','primary','启动清单实验  →');start.type='submit';start.disabled=true;footer.append(start);form.append(body,footer);target.append(form);
  let available=[];
  function paint(){
    const n=selection.evolution.length,m=selection.test.length;
    summary.textContent=`${n} 个进化样本 = ${n} 轮 RSI；${m} 个测试样本 × ${n+1} 个版本 = ${(n+1)*m} 次测试 task。每个 task 按配置执行全部 run，包含 critic 与完整评测。`;
    start.disabled=!n||!m;
    for(const key of ['evolution','test']){
      columns[key].replaceChildren();const other=key==='evolution'?'test':'evolution';
      for(const item of available){
        const label=make('label','input-card'),check=make('input'),image=make('img','campaign-thumbnail'),info=make('div','input-card-info');
        check.type='checkbox';check.value=item.path;check.checked=selection[key].includes(item.path);check.disabled=selection[other].includes(item.path)||(key==='evolution'&&!['smoke','evolution'].includes(item.split));
        check.setAttribute('aria-label',key+' '+(item.case_id||item.path));
        image.src=item.thumbnail_url;image.loading='lazy';image.alt='';image.width=160;image.height=90;
        const order=selection[key].indexOf(item.path);info.append(make('strong','',`${order>=0?order+1+'. ':''}${item.case_id||item.display_name||item.path}`),make('small','',item.category||item.split));
        check.onchange=()=>{selection[key]=check.checked?[...selection[key],item.path]:selection[key].filter(p=>p!==item.path);paint();};label.append(check,image,info);columns[key].append(label);
      }
    }
  }
  try{available=(await api('/api/inputs')).filter(row=>row.benchmark&&!['held-out','heldout','held_out'].includes(row.split));if(!form.isConnected)return;paint();if(!available.length)summary.textContent='暂无可用的 4DCodeBench 样本。';}catch(error){summary.textContent=error.message;}
  form.onsubmit=async e=>{e.preventDefault();start.disabled=true;notice();try{const config=readConfig(controls,cfg);config.campaign={...config.campaign,outer_rsi:true,trial_enabled:true};if(!config.model)throw Error('请选择重建模型。');const record=await post('/api/campaigns',{config,evolution_inputs:selection.evolution,test_inputs:selection.test});await refresh();S.mode='campaigns';await selectRecord(record.id);}catch(error){notice(error.message);}finally{if(form.isConnected)paint();}};
}
async function campaignAction(id,action){notice();try{await post(`/api/campaigns/${encodeURIComponent(id)}/${action}`,{});await refresh();if(S.mode==='campaigns'&&S.id===id)await selectRecord(id,true);notice(action==='pause'?'已请求暂停：正在途的调用和工具结束后暂停。':action==='stop'?'已请求停止：取消待执行任务，并保留调用与结果。':action==='confirm'?'已采纳本轮版本，继续进化。':'实验继续执行。');}catch(e){notice(e.message);}}
function renderCampaign(target,record){
  const actions=[button('新建实验',()=>{clearSelection();showCampaignHome();},'secondary'),button('实验结果与分析 ↗',()=>window.open('/static/experiment.html?campaign='+encodeURIComponent(record.id),'_blank','noopener'),'primary')];
  if(['scheduled','queued','running','pausing','paused','awaiting_confirmation'].includes(record.status)){
    const queued=['scheduled','queued'].includes(record.status);if(queued)actions.push(button('取消排队',()=>campaignAction(record.id,'stop'),'secondary danger'));
    else{
    const paused=['pausing','paused'].includes(record.status);
    actions.push(button(paused?'继续实验':'暂停实验',()=>campaignAction(record.id,paused?'resume':'pause'),'secondary'),button('停止实验',()=>campaignAction(record.id,'stop'),'secondary danger'));
    if(record.pending_candidate)actions.push(button('在本实验采纳并继续',()=>campaignAction(record.id,'confirm'),'primary'));
    }
  }
  heading(target,`进化实验 ${short(record.id)}`,`${STATUS[record.status]||record.status} · ${time(record.created_at)}`,actions,'EXPERIMENT LOG');
  const c=record.config?.campaign||{},batches=record.benchmarks||{},initial=batches[record.baseline_batch_id],plan=record.resource_plan;
  const pipeline=record.schedule_policy==='pipeline_v1'?'初始 baseline 与首轮进化并行，后续进化与测试并行；比较结果在两组测试完成后生成。':'按本实验启动时冻结的调度策略执行。';
  target.append(make('div','policy-note',`外层 RSI：${c.outer_rsi===false?'关闭':'开启'} · 版本测试：${c.trial_enabled===false?'关闭':'开启'} · 采纳：${c.auto_adopt===false?'手动确认':'实验策略自动采纳'}。${pipeline}`));
  if(record.usage)target.append(make('p','metadata',`实验实际累计：${usageText(record.usage)} · 每个调用仅统计一次，包含全部测试与 RSI。`));
  if(plan)target.append(make('p','metadata',`当前资源计划：${plan.task_slots} 个 task 名额，${plan.test_workers} 个测试 worker；CPU / RAM / GPU 由全局资源队列按 task 阶段分配。`));
  if(['pausing','paused','stopping'].includes(record.status))target.append(make('p','policy-note',record.status==='paused'?'所有 worker 已在安全边界暂停，继续后沿用当前上下文。':record.status==='pausing'?'不再发起新调用，等待正在途的 API、工具或指标评估结束。':'正在停止全部实验 worker；已发生调用、版本和结果继续保留。'));
  if(record.error)target.append(paragraph(record.error,'error'));
  function tasksPanel(parent,batch,title){if(!batch)return;const card=make('section','panel summary-panel');card.append(make('h3','',title),make('p','metadata',`固定版本 ${batch.version} · ${STATUS[batch.status]||batch.status} · 已返回 ${batch.results?.length||0} / ${batch.expected_tasks??batch.task_ids?.length??0}`));for(const id of batch.task_ids||[]){const task=(S.state.tasks||[]).find(t=>t.id===id),row=batch.results?.find(r=>r.record_id===id);card.append(button(`${task?.title||id} · ${STATUS[row?.status||task?.status]||row?.status||task?.status||'已排队'}`,()=>selectTask(id),'text-button'));}parent.append(card);}
  tasksPanel(target,initial,'实验前 Baseline');
  if(!record.rounds?.length&&!initial)empty(target,'等待实验进度','关联任务、固定版本和测试结果会随执行更新。','⌘');
  for(const round of record.rounds||[]){
    const card=make('section','panel experiment-round'),head=make('div','trial-header'),afterBatch=batches[round.test_batch_id],beforeBatch=batches[round.baseline_batch_id];
    head.append(make('h3','',`第 ${round.round||'—'} 轮 · ${short(round.tested_version||round.candidate)}`),badge(round.status||round.decision?.decision));card.append(head,make('p','metadata',`父版本 ${short(round.parent)} → 测试版本 ${short(round.tested_version||round.candidate)} · ${afterBatch?`测试 ${afterBatch.results?.length||0} / ${afterBatch.expected_tasks??afterBatch.task_ids?.length??0}`:'未启用测试'}`));
    if(round.task_id)card.append(button('打开本轮重建任务',()=>selectTask(round.task_id),'text-button'));
    if(round.error)card.append(paragraph(round.error,'error'));
    if(round.decision)card.append(make('p','check-description',round.decision.mode==='experiment_auto'?'已按实验策略采纳，后续进化沿用该版本；测试使用固定快照，完成后生成比较结果。':round.decision.mode==='manual'?'版本采纳由你确认；后续进化等待本轮确认。':round.decision.reason||'保留独立指标作为参考。'));
    const base=round.baseline||beforeBatch?.results||[],after=round.candidate_results||afterBatch?.results||[],paths=[...new Set([...base,...after].map(r=>r.task_id))];
    for(const path of paths){const before=base.find(r=>r.task_id===path),candidate=after.find(r=>r.task_id===path),holder=make('div'),d=detail(path,holder);d.addEventListener('toggle',()=>{if(d.open&&!holder.childElementCount){holder.append(metricPanel(before||{},candidate,'测试任务的指标对照','benchmark'));for(const[label,row]of[['父版本',before],['本轮版本',candidate]])if(row){holder.append(make('p','metadata',`${label} ${row.version} · 快照 ${row.snapshot_sha256||'历史记录未提供'} · ${STATUS[row.status]||row.status}`));if(row.record_id)holder.append(button(`打开${label}任务`,()=>selectTask(row.record_id),'text-button'));}}});card.append(d);}
    if(afterBatch&&afterBatch.status==='running')tasksPanel(card,afterBatch,'本轮测试进度');
    card.append(rawDetails('本轮完整记录',round));target.append(card);
  }
  if(record.progress?.length){const progress=make('section','panel summary-panel');progress.append(make('h3','','最近执行进度'));record.progress.slice(-8).forEach(row=>progress.append(button(`${row.label||''} · ${row.source||short(row.task_id)} · ${short(row.version)}`,()=>selectTask(row.task_id),'text-button')));target.append(progress);}
  target.append(rawDetails('完整实验配置与记录',record));
}

async function openSettings(task=null){notice();const dialog=$('#settings-dialog');S.settings={task_id:task?.id||null,task,base:normalizeConfig(task?.config||S.state.config)};$('#settings-title').textContent=task?'本任务的模型与设置':SAFE?'共享全局默认设置':'模型与运行默认设置';$('#settings-note').textContent=task?(task.runs?.length?'运行配置已固定。任务结束前仍可调整外层 RSI 和新版本试验开关。':'设置只保存到当前 task，首次 run 时固定执行环境。'):SAFE?'这里修改两工作台共享的全局设置。safe 新任务默认每 run 50 次编辑 API，编辑与 run critic 的累计 Token 不限；以新任务表单为准。':'默认设置用于新任务。每个 task 可单独选择模型、run 上限与 RSI 行为。';$('#config-error').hidden=true;$('#advanced-settings').open=false;renderSettingsFields();const health=$('#health-info');health.replaceChildren();Object.entries(S.state.health||{}).forEach(([key,value])=>{const row=make('div','health-entry');row.append(make('span','',key),make('span','',typeof value==='object'?json(value):String(value)));health.append(row);});dialog.showModal();if(!task)try{const cfg=await api('/api/config');if(S.settings&&!S.settings.task_id){S.settings.base=normalizeConfig(cfg);renderSettingsFields();}}catch(e){$('#config-error').textContent=e.message;$('#config-error').hidden=false;}}
function renderSettingsFields(){const draft=S.settings;if(!draft)return;const locked=!!draft.task?.runs?.length,allLocked=!!draft.task_id&&(taskBusy(draft.task_id)||ACTIVE.has(draft.task?.status)||draft.task?.status==='completed'||!!draft.task?.finalized_at);const form=configForm(draft.base,{detailed:true,locked,allLocked,includeCampaign:!draft.task_id&&!SAFE});$('#settings-fields').replaceChildren(form);$('#config-json').value=json(draft.base);$('#config-json').disabled=locked||allLocked;$('#apply-json').disabled=locked||allLocked;$('#save-config').disabled=allLocked;}
$('#apply-json').onclick=()=>{try{S.settings.base=normalizeConfig(JSON.parse($('#config-json').value));renderSettingsFields();$('#config-error').hidden=true;}catch(e){$('#config-error').textContent=e.message;$('#config-error').hidden=false;}};
$('#settings-form').onsubmit=async e=>{e.preventDefault();const draft=S.settings,save=$('#save-config');if(!draft)return;save.disabled=true;$('#config-error').hidden=true;try{let value=readConfig($('#settings-fields'),draft.base);const path=draft.task_id?route('/config',draft.task_id):'/api/config';if(SAFE&&draft.task_id)value.trial_enabled=false;if(draft.task_id&&draft.task.runs?.length)value={outer_rsi:value.outer_rsi,trial_enabled:value.trial_enabled};await api(path,{method:'PATCH',body:json(value)});$('#settings-dialog').close();await refresh();if(draft.task_id)await selectTask(draft.task_id,true);else if(!S.id){S.composer=null;if(S.mode==='tasks')showHome(true);else if(S.mode==='campaigns')showCampaignHome();}notice('设置已保存。');}catch(err){$('#config-error').textContent=err.message;$('#config-error').hidden=false;}finally{save.disabled=false;}};
document.querySelectorAll('[data-mode]').forEach(n=>n.onclick=()=>switchMode(n.dataset.mode));document.querySelectorAll('[data-close]').forEach(n=>n.onclick=()=>$('#'+n.dataset.close).close());$('#new-task').onclick=()=>{notice();showHome(true);};$('#settings').onclick=()=>openSettings();$('#refresh').onclick=refresh;$('#search').oninput=updateSidebar;$('#menu').onclick=()=>document.body.classList.toggle('menu-open');document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu'))document.body.classList.remove('menu-open');});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});setInterval(()=>{if(!document.hidden)refresh();},5000);
refresh().then(()=>{setNavigation();const taskMatch=location.hash.match(/^#task\/([^/]+)(?:\/(scene|model|rsi|flow|world|compare))?$/);if(taskMatch){S.mode='tasks';selectTask(decodeURIComponent(taskMatch[1]),false,taskMatch[2]||'scene');return;}const match=location.hash.match(/^#(task|version|campaign)\/(.+)$/);if(match&&(!SAFE||match[1]!=='campaign')){S.mode=match[1]==='task'?'tasks':match[1]==='version'?'versions':'campaigns';select(decodeURIComponent(match[2]));}else showHome();});
